// Offline review-intelligence mock for UI work (#17).
//
// The data is generated by `cargo test` from fixtures/analysis/demo-cli-14921
// and typed with the ts-rs generated contracts, so `pnpm -C app check` fails if
// the fixture drifts from the Rust types. Do not hand-write duplicate types.
// The Review screen (#38) renders live data from the #33 API; this mock stays
// for offline UI work.
import type { AnalysisRun } from '../generated/AnalysisRun';
import type { DemoIntelligence } from '../generated/DemoIntelligence';
import type { ReviewFinding } from '../generated/ReviewFinding';
import { demoIntelligence, demoIntelligenceWithLlm } from '../generated/fixtures/demoIntelligence';

export type { DemoIntelligence };

/** The demo bundle. The LLM hypothesis is opt-in and off by default. */
export function mockIntelligence(includeLlm = false): DemoIntelligence {
  return includeLlm ? demoIntelligenceWithLlm : demoIntelligence;
}

/** Findings that apply to the current snapshot for one file. */
export function currentFindingsForFile(bundle: DemoIntelligence, fileId: string): ReviewFinding[] {
  return bundle.findings.filter(
    (f) => f.anchor.fileId === fileId
      && (f.applicability === 'current_exact' || f.applicability === 'current_related'),
  );
}

/** "0 issues found" is only allowed when every provider fully succeeded. */
export function mayClaimNoIssues(runs: AnalysisRun[], findings: ReviewFinding[]): boolean {
  return runs.length > 0 && runs.every((r) => r.status === 'succeeded') && findings.length === 0;
}
